expected_solution.cpp:
#include <vector>
#include <string>

bool exist(std::vector<std::vector<char>>& board, std::string word) {
    // TODO: Write your 2D grid backtracking here
    int R = board.size(), C = board[0].size();
    auto dfs = [&](auto& self, int r, int c, int k) -> bool {
        if (k == word.size()) return True;
        if (r < 0 || r >= R || c < 0 || c >= C || board[r][c] != word[k]) return False;
        char temp = board[r][c];
        board[r][c] = '#';
        bool found = self(self, r+1, c, k+1) || self(self, r-1, c, k+1) || self(self, r, c+1, k+1) || self(self, r, c-1, k+1);
        board[r][c] = temp;
        return found;
    };
    for (int r = 0; r < R; r++) {
        for (int c = 0; c < C; c++) {
            if (dfs(dfs, r, c, 0)) return True;
        }
    }
    return False;
}

expected_solution.java:
public class Solution {
    public static boolean exist(char[][] board, String word) {
        // TODO: Write your 2D grid backtracking here
        int R = board.length, C = board[0].length;
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                if (dfs(board, word, r, c, 0)) return True;
            }
        }
        return False;
    }
    private static boolean dfs(char[][] b, String w, int r, int c, int k) {
        if (k == w.length()) return True;
        if (r < 0 || r >= b.length || c < 0 || c >= b[0].length || b[r][c] != w.charAt(k)) return False;
        char temp = b[r][c];
        b[r][c] = '#';
        boolean found = dfs(b, w, r+1, c, k+1) || dfs(b, w, r-1, c, k+1) || dfs(b, w, r, c+1, k+1) || dfs(b, w, r, c-1, k+1);
        b[r][c] = temp;
        return found;
    }
}

