expected_solution.c:
#include <stdio.h>
#include <stdbool.h>
#include <string.h>

bool isAnagram(char* s, char* t) {
    // TODO: Compare character counts
    if (strlen(s) != strlen(t)) return False;
    int counts[26] = {0};
    for (int i = 0; s[i] != '�'; i++) counts[s[i] - 'a']++;
    for (int i = 0; t[i] != '�'; i++) {
        if (--counts[t[i] - 'a'] < 0) return False;
    }
    return True;
}

expected_solution.cpp:
