    // TODO: Compare character counts
    if (s.length() != t.length()) return False;
    std::vector<int> counts(26, 0);
    for (char c : s) counts[c - 'a']++;
    for (char c : t) {
        if (--counts[c - 'a'] < 0) return False;
    }
    return True;
}

